  /// 외화별 반품 배송비·교환 배송비(이슈 #130). 키는 판매 통화 코드이고 기본 통화(KRW)는 넣지 않습니다. 금액은 그 통화의 최소 단위입니다. 상품이 정한 통화 값이 상점 값보다 앞섭니다. 정하지 않은 외화로는 배송 상품을 팔지 않습니다. 주면 맵 전체를 바꿉니다.
  Map<String, CurrencyRefundFees>? get currencies => (_j['currencies'] as Map?)?.cast<String, CurrencyRefundFees>();
}

/// 정책 해석에 쓰는 상품 값 — 상품별 덮어쓰기.
class RefundPolicyProductInput {
  /// [RefundPolicyProductInput]을 만듭니다.
  const RefundPolicyProductInput({this.refundPolicy});

  /// 상품별 덮어쓰기. 없으면 상점 기본을 그대로 씁니다.
  final RefundPolicyPatch? refundPolicy;

  /// 쿼리 파라미터로 바꿉니다. null인 값은 뺍니다.
  Map<String, Object?> toJson() => {if (refundPolicy != null) 'refundPolicy': refundPolicy};
}

/// 반품·교환 배송비 키 — 배송이 없는 상품의 정책에는 두지 않습니다.
const REFUND_POLICY_DELIVERY_FEE_KEYS = <String>['returnDeliveryFee', 'exchangeDeliveryFee'];
